@Service
public class OrderTools {
    @Tool(description = "按订单号查询订单状态和物流信息。仅能查询当前登录用户自己的订单。")
    public OrderSummary getOrder(
            @ToolParam(description = "订单号，如 O20261031001") String orderNo) {
        User u = SecurityContext.currentUser();                    // 按用户权限
        Order o = orderService.findOwned(u.id(), orderNo)
                .orElseThrow(() -> new ToolException("未找到该订单或无权访问"));
        return OrderSummary.of(o);                                 // 精简字段
    }
}
// spring-ai-starter-mcp-server-webmvc：暴露为 Streamable HTTP MCP 服务
@Bean ToolCallbackProvider tools(OrderTools t) { return MethodToolCallbackProvider.builder().toolObjects(t).build(); }
